def solve_backtracking(pieces, bin_capacity, target_bins, timeout=30):
    bins = [0.0] * target_bins
    start_time = time.time()

    def backtrack(idx):
        if time.time() - start_time > timeout:
            return "TIMEOUT"
        if idx == len(pieces):
            return True

        p = pieces[idx]
        tried_weights = set()
        for i in range(target_bins):
            if bins[i] + p <= bin_capacity + 1e-7:
                weight = round(bins[i], 2)
                if weight not in tried_weights:
                    bins[i] += p
                    res = backtrack(idx + 1)
                    if res == True:
                        return True
                    if res == "TIMEOUT":
                        return "TIMEOUT"
                    bins[i] -= p
                    tried_weights.add(weight)
        return False

    res = backtrack(0)
    return res

